export const roadmapDays: RoadmapDay[] = rawRoadmapDays.flatMap((day) => {
  if (day.day !== 5) return [day];
  return [{ ...day, items: dayFiveItems }, daySix];
});

export const roadmapItems = roadmapDays.flatMap((day) => day.items);

